def adjac(ele, sub=[]):
    if not ele:
        return [sub] if sub else []
    else:
        current = ele[0]
        neighbors = [current - 1, current, current + 1]
        return [coord for n in neighbors for coord in adjac(ele[1:], sub + [n])]

def get_coordinates(test_tup):
    return [coord for coord in adjac(test_tup) if len(coord) == len(test_tup)]

